package org.traccar.protocol;

import io.netty.buffer.ByteBuf;
import io.netty.buffer.Unpooled;
import io.netty.channel.Channel;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.runners.MockitoJUnitRunner;
import java.net.SocketAddress;
import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.class)
public class GalileoProtocolDecoderTest {

    @Mock
    private Protocol protocol;

    @Mock
    private Channel channel;

    @Mock
    private SocketAddress remoteAddress;

    @Test
    public void GalileoProtocolDecoderProtocolProvidedTest() {
        new GalileoProtocolDecoder(protocol);
    }

    @Test
    public void decodeNonByteBufMessageTest() throws Exception {
        GalileoProtocolDecoder decoder = new GalileoProtocolDecoder(protocol);
        Object msg = new Object();
        decoder.decode(channel, remoteAddress, msg);
    }

    @Test
    public void decodeByteBufMessageTest() throws Exception {
        GalileoProtocolDecoder decoder = new GalileoProtocolDecoder(protocol);
        ByteBuf msg = Unpooled.buffer();
        decoder.decode(channel, remoteAddress, msg);
    }

    @Test
    public void decodeByteBufMessageWithChannelTest() throws Exception {
        when(channel.writeAndFlush(any())).thenReturn(null);

        GalileoProtocolDecoder decoder = new GalileoProtocolDecoder(protocol);
        ByteBuf msg = Unpooled.buffer();
        decoder.decode(channel, remoteAddress, msg);
    }
}
```
